function validate([m, n, head]) {
  if (!Number.isInteger(m) || m < 1 || m > 100000) return 'm is between 1 and 10^5.';
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 10^5.';
  if (m * n > 100000) return 'm * n is at most 10^5.';
  if (head.length < 1 || head.length > m * n) return 'The list needs between 1 and m * n nodes.';
  if (head.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each node value is between 0 and 1000.';
  return null;
}

