function spiralMatrix(m, n, head) {
  const matrix = Array.from({ length: m }, () => new Array(n).fill(-1));
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  let row = 0;
  let col = 0;
  let dir = 0;
  let node = head;

  while (node) {
    matrix[row][col] = node.val;
    node = node.next;
    const nextRow = row + directions[dir][0];
    const nextCol = col + directions[dir][1];
    const blocked = nextRow < 0 || nextRow >= m || nextCol < 0 || nextCol >= n || matrix[nextRow][nextCol] !== -1;
    if (blocked) {
      dir = (dir + 1) % 4;
    }
    row += directions[dir][0];
    col += directions[dir][1];
  }
  return matrix;
}

