function generate(rand, size) {
  let m, n, length;
  if (size === 'large') {
    const shapes = [[100, 100], [1, 2000], [2000, 1], [40, 50], [7, 300], [150, 120]];
    [m, n] = shapes[Math.floor(rand() * shapes.length)];
    const cap = Math.min(2000, m * n);
    length = rand() < 0.5 ? cap : 1 + Math.floor(rand() * cap);
  } else {
    m = 1 + Math.floor(rand() * 5);
    n = 1 + Math.floor(rand() * 5);
    length = rand() < 0.4 ? m * n : 1 + Math.floor(rand() * m * n);
  }
  const top = rand() < 0.5 ? 9 : 1000;
  const head = Array.from({ length }, () => Math.floor(rand() * (top + 1)));
  return [m, n, head];
}
